 public static void Create(){Directory.CreateDirectory("Assets/"+Folder+"/Models");var m=SportsEventAuthoring.Begin<DodgeMatch>(Folder);m.option=0;m.teamA=m.teamB=4;m.NormalizeSetup();m.feedback.clips=(AudioClip[])LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create().Clone();m.feedback.clips[0]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckCornhole/Audio/Launch.wav");m.feedback.clips[5]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDockDiving/Audio/Exceptional cheer.wav");
 var charcoal=SportsEventAuthoring.Mat(Folder,"Athletic navy rubber",new Color(.035f,.075f,.12f),.15f);var blue=SportsEventAuthoring.Mat(Folder,"Blue woven trampoline",new Color(.055f,.28f,.42f),.22f);var orange=SportsEventAuthoring.Mat(Folder,"Orange woven trampoline",new Color(.47f,.18f,.035f),.22f);var steel=SportsEventAuthoring.Mat(Folder,"Spring and safety frame steel",new Color(.3f,.38f,.45f),.7f);steel.SetFloat("_Metallic",.75f);var cream=SportsEventAuthoring.Mat(Folder,"Readable court markings",new Color(.94f,.9f,.72f),.18f);var safe=SportsEventAuthoring.Contact(Folder,"Trampoline truck ground",.8f,.02f);var wallContact=SportsEventAuthoring.Contact(Folder,"Padded arena rail",.22f,.25f);
 var floor=SportsEventAuthoring.Box("Structural arena rubber floor",new Vector3(0,-.28f,0),new Vector3(38,.5f,30),charcoal,safe);floor.AddComponent<DodgeGround>();var weave=Weave();var coil=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/TruckBeerPong/Models/Seven-turn visible launch spring.asset");if(coil==null)throw new Exception("Existing collection spring mesh required");for(int x=-1;x<=1;x+=2)for(int z=-1;z<=1;z+=2){var tile=SportsEventAuthoring.Box("Actual contact trampoline "+x+" "+z,new Vector3(x*7.8f,.015f,z*5.6f),new Vector3(14.4f,.18f,9.6f),z<0?blue:orange,safe);var bounce=tile.AddComponent<DodgeTrampoline>();var bed=new GameObject("Compression-only woven bed").transform;bed.position=tile.transform.position+Vector3.up*.101f;bounce.bed=bed;tile.GetComponent<Renderer>().enabled=false;SportsEventAuthoring.Box("Flexible visible trampoline fabric",new Vector3(0,-.04f,0),new Vector3(14.4f,.08f,9.6f),z<0?blue:orange,null,bed);Part(bed,"Tensioned visible woven fabric",weave,cream).transform.localPosition=Vector3.up*.004f;foreach(int side in new[]{-1,1}){LWS.TruckFieldGoal.Editor.FieldGoalModels.Cylinder(null,"Rounded padded trampoline frame",new Vector3(x*7.8f+side*7.4f,.18f,z*5.6f-5),new Vector3(x*7.8f+side*7.4f,.18f,z*5.6f+5),.15f,steel);LWS.TruckFieldGoal.Editor.FieldGoalModels.Cylinder(null,"Rounded padded trampoline frame",new Vector3(x*7.8f-7.4f,.18f,z*5.6f+side*5),new Vector3(x*7.8f+7.4f,.18f,z*5.6f+side*5),.15f,steel);for(int n=0;n<5;n++){var spring=Part(null,"Installed seven-turn exposed trampoline spring",coil,steel);spring.transform.position=new Vector3(x*7.8f+side*7.25f,.16f,z*5.6f-4+n*2);spring.transform.rotation=Quaternion.Euler(0,0,90);spring.transform.localScale=new Vector3(.11f,.5f,.11f);}}}
 var glass=SportsEventAuthoring.Mat(Folder,"Transparent upper safety wall",new Color(.24f,.6f,.72f,.07f),.08f);glass.SetFloat("_Surface",1);glass.SetFloat("_Blend",0);glass.SetFloat("_SrcBlend",5);glass.SetFloat("_DstBlend",10);glass.SetFloat("_ZWrite",0);glass.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");glass.renderQueue=3000;var path=Boundary();for(int i=0;i<path.Length-1;i++){var delta=path[i+1]-path[i];var rail=SportsEventAuthoring.Box("Continuous rounded padded arena wall "+i,(path[i]+path[i+1])*.5f+Vector3.up*3,new Vector3(.35f,6,delta.magnitude+.05f),charcoal,wallContact);rail.transform.rotation=Quaternion.LookRotation(delta);rail.GetComponent<Renderer>().sharedMaterial=glass;var low=SportsEventAuthoring.Box("Low padded visible safety rail "+i,(path[i]+path[i+1])*.5f+Vector3.up*.3f,new Vector3(.36f,.6f,delta.magnitude+.05f),charcoal);low.transform.rotation=rail.transform.rotation;LWS.TruckFieldGoal.Editor.FieldGoalModels.Cylinder(null,"Rounded top rail",path[i]+Vector3.up*6,path[i+1]+Vector3.up*6,.045f,steel);}var roof=SportsEventAuthoring.Box("High safety ceiling collision",Vector3.up*15.5f,new Vector3(38,.5f,30),charcoal,safe);roof.GetComponent<Renderer>().enabled=false;roof.AddComponent<DodgeGround>();for(int z=-1;z<=1;z+=2){var mark=SportsEventAuthoring.Label("Team wall sign",z<0?"BLUE / BOUNCE & RETURN":"ORANGE / BOUNCE & RETURN",new Vector3(0,.3f,z*11.6f),.14f,z<0?new Color(.2f,.7f,1):new Color(1,.5f,.1f));mark.transform.rotation=Quaternion.Euler(90,0,0);}
 m.fighters=new DodgeFighter[8];for(int i=0;i<8;i++){var truck=SportsEventAuthoring.Truck(m,Folder,"Dodgeball competitor "+(i+1),new Vector3((i%4-1.5f)*4.8f,.85f,i<4?-9:9),i);SportsRallyAuthoring.FitTruck(truck);truck.maxSpeed=9;truck.reverseSpeed=6;truck.motorTorque=13;truck.brakeTorque=20;truck.steerAngle=50;truck.grip=1.65f;truck.body.centerOfMass=new Vector3(0,-.12f,0);truck.body.maxLinearVelocity=22;truck.body.maxAngularVelocity=5;truck.shape.sharedMaterial=SportsEventAuthoring.Contact(Folder,"Truck physical impact",.2f,.08f);var f=truck.gameObject.AddComponent<DodgeFighter>();f.match=m;f.truck=truck;f.slot=i;f.teamTrim=new Renderer[2];for(int side=0;side<2;side++){var stripe=SportsEventAuthoring.Box("Team stripe "+side,new Vector3(side==0?-.81f:.81f,.46f,0),new Vector3(.04f,.18f,2.7f),cream,null,truck.transform);stripe.transform.SetParent(truck.visuals,true);f.teamTrim[side]=stripe.GetComponent<Renderer>();}var halo=new GameObject("Timed visible strike crescent").transform;halo.SetParent(truck.visuals,true);halo.SetPositionAndRotation(truck.transform.position+Vector3.up*.35f,Quaternion.identity);var line=halo.gameObject.AddComponent<LineRenderer>();line.useWorldSpace=false;line.positionCount=25;line.widthMultiplier=.07f;line.sharedMaterial=cream;for(int k=0;k<25;k++){float a=Mathf.Lerp(-85,85,k/24f)*Mathf.Deg2Rad;line.SetPosition(k,new Vector3(Mathf.Sin(a)*2.6f,0,Mathf.Cos(a)*2.6f));}halo.gameObject.SetActive(false);f.strikeHalo=halo;f.hit=Impact("Pooled elimination sparkle "+i);m.fighters[i]=f;}
 m.balls=new DodgeBall[3];var ballMaterial=SportsEventAuthoring.Mat(Folder,"Glossy physical dodgeball shell",Color.white,.7f);var ballPhysics=SportsEventAuthoring.Contact(Folder,"Bouncy dodgeball",.18f,.82f);ballPhysics.bounceCombine=PhysicsMaterialCombine.Maximum;for(int i=0;i<m.balls.Length;i++){var g=GameObject.CreatePrimitive(PrimitiveType.Sphere);g.name="Actual team-colored dodgeball "+i;g.transform.position=new Vector3((i-1)*5,2.4f,0);g.transform.localScale=Vector3.one*1.15f;var b=g.AddComponent<Rigidbody>();b.mass=.9f;b.linearDamping=.035f;b.angularDamping=.06f;b.interpolation=RigidbodyInterpolation.Interpolate;b.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;b.maxLinearVelocity=24;b.maxAngularVelocity=30;var ball=g.AddComponent<DodgeBall>();ball.body=b;ball.shape=g.GetComponent<SphereCollider>();ball.shape.sharedMaterial=ballPhysics;ball.shell=g.GetComponent<Renderer>();ball.shell.sharedMaterial=ballMaterial;ball.match=m;ball.index=i;ball.trail=g.AddComponent<TrailRenderer>();ball.trail.sharedMaterial=SportsChaosAuthoring.Flare(Folder);ball.trail.time=.32f;ball.trail.startWidth=.35f;ball.trail.endWidth=0;ball.trail.minVertexDistance=.1f;ball.trail.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;b.isKinematic=true;m.balls[i]=ball;}
 m.views=SportsRallyAuthoring.Views(m,m.fighters.Select(f=>f.truck).ToArray());m.views.groundOffset=new Vector3(0,5,-10);m.views.groundLookAhead=3;m.views.broadcast.view.orthographic=true;m.views.broadcast.view.farClipPlane=160;m.fit=m.views.broadcast.gameObject.AddComponent<SportsCameraFit>();m.fit.cameraTarget=m.views.broadcast.view;m.fit.arenaFit=true;m.fit.arenaBounds=new Bounds(Vector3.up*5,new Vector3(37,12,29));m.fit.topInset=.08f;m.fit.bottomInset=.07f;m.fit.Apply();m.replay=SportsRallyAuthoring.Replay(m,m.fighters.Select(f=>f.truck.visuals).Concat(m.balls.Select(b=>b.transform)).ToArray());m.replay.capacity=2400;foreach(var ghost in m.replay.ghosts)foreach(var trail in ghost.GetComponentsInChildren<TrailRenderer>(true)){trail.emitting=false;trail.Clear();}m.replayColors=m.gameObject.AddComponent<DodgeReplayColors>();m.replayColors.balls=m.balls;m.replayColors.replay=m.replay;
 var dressing=new GameObject("Installed arena event dressing").transform;for(int i=0;i<10;i++)SportsRallyAuthoring.Prop(dressing,"Assets/RoadPropsPack/URP/Prefabs/RoadBlock01_URP.prefab",new Vector3(-18+i*4,0,16),new Vector3(3.5f,1,.7f));SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);SportsBroadcastAuthoring.ApplyScene();SportsEventAuthoring.Save(Folder);Validate();}
 static GameObject Part(Transform parent,string name,Mesh mesh,Material material){var g=new GameObject(name);g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=material;return g;}
 static Mesh Weave(){string path="Assets/"+Folder+"/Models/Woven trampoline bed.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh!=null)return mesh;var vertices=new List<Vector3>();var triangles=new List<int>();void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d){int k=vertices.Count;vertices.AddRange(new[]{a,b,c,d});triangles.AddRange(new[]{k,k+1,k+2,k,k+2,k+3});}for(int i=-28;i<=28;i++){float x=i*.25f;Quad(new Vector3(x-.012f,0,-4.6f),new Vector3(x-.012f,0,4.6f),new Vector3(x+.012f,0,4.6f),new Vector3(x+.012f,0,-4.6f));}for(int i=-18;i<=18;i++){float z=i*.25f;Quad(new Vector3(-7,0,z-.012f),new Vector3(-7,0,z+.012f),new Vector3(7,0,z+.012f),new Vector3(7,0,z-.012f));}mesh=new Mesh{name="One-drawcall actual woven trampoline mesh"};mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static Vector3[] Boundary(){var points=new List<Vector3>();for(int corner=0;corner<4;corner++){float a=corner*Mathf.PI*.5f;var center=new Vector3(Mathf.Cos(a+Mathf.PI*.25f)>0?13:-13,0,Mathf.Sin(a+Mathf.PI*.25f)>0?9:-9);for(int k=0;k<=12;k++){float angle=a+k*Mathf.PI*.5f/12;points.Add(center+new Vector3(Mathf.Cos(angle)*4,0,Mathf.Sin(angle)*4));}}points.Add(points[0]);return points.ToArray();}
 static ParticleSystem Impact(string name){var p=new GameObject(name).AddComponent<ParticleSystem>();p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=p.main;main.loop=false;main.playOnAwake=false;main.startLifetime=.5f;main.startSpeed=4;main.startSize=.2f;main.startColor=new Color(1,.6f,.2f);main.maxParticles=36;main.simulationSpace=ParticleSystemSimulationSpace.World;var emission=p.emission;emission.rateOverTime=0;emission.SetBursts(new[]{new ParticleSystem.Burst(0,24)});p.GetComponent<ParticleSystemRenderer>().sharedMaterial=SportsChaosAuthoring.Flare(Folder);return p;}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<DodgeMatch>();if(m==null){EditorSceneManager.OpenScene(Scene);m=UnityEngine.Object.FindAnyObjectByType<DodgeMatch>();}if(m==null||m.fighters.Length!=8||m.balls.Length!=3||m.replay.sources.Length!=11||m.replayColors==null||UnityEngine.Object.FindObjectsByType<DodgeTrampoline>(FindObjectsInactive.Include).Length!=4||m.feedback.clips.Any(c=>c==null))throw new Exception("Dodgeball actual trampoline/ball/view/replay references incomplete");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("One listener required");Debug.Log("DODGE_NATIVE_SCENE_VALIDATED");}
